pub mod hsl;
pub mod rgb;
pub mod converter;

pub use hsl::Hsl;
pub use rgb::Rgb;
pub use converter::ColorConverter;

use super::hsl::Hsl;

/// RGB color with channels stored as 32-bit floats (mirrors the C++ `RGB` class).
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }

    /// Convert to HSL. Hue is returned in degrees in [0, 360),
    /// saturation and lightness in [0, 1].
    pub fn to_hsl(&self) -> Hsl {
        let min = self.r.min(self.g).min(self.b);
        let max = self.r.max(self.g).max(self.b);
        let delta = max - min;
        let l = (max + min) / 2.0;

        if delta == 0.0 {
            return Hsl::new(0.0, 0.0, l);
        }

        let s = if l < 0.5 {
            delta / (max + min)
        } else {
            delta / (2.0 - max - min)
        };

        let mut h = if max == self.r {
            (self.g - self.b) / delta
        } else if max == self.g {
            (self.b - self.r) / delta + 2.0
        } else {
            (self.r - self.g) / delta + 4.0
        };
        h *= 60.0;
        if h < 0.0 {
            h += 360.0;
        }

        Hsl::new(h, s, l)
    }
}

use super::rgb::Rgb;

/// HSL color: hue in degrees, saturation and lightness as 32-bit floats
/// (mirrors the C++ `HSL` class).
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Hsl { h, s, l }
    }

    /// Convert back to RGB using the classic hue2rgb helper with the
    /// hue normalized to [0, 1].
    pub fn to_rgb(&self) -> Rgb {
        if self.s == 0.0 {
            return Rgb::new(self.l, self.l, self.l);
        }

        let q = if self.l < 0.5 {
            self.l * (1.0 + self.s)
        } else {
            self.l + self.s - self.l * self.s
        };
        let p = 2.0 * self.l - q;

        let hk = self.h / 360.0;
        let tr = hk + 1.0 / 3.0;
        let tg = hk;
        let tb = hk - 1.0 / 3.0;

        Rgb::new(
            hue_to_rgb(p, q, tr),
            hue_to_rgb(p, q, tg),
            hue_to_rgb(p, q, tb),
        )
    }
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t * 6.0 < 1.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t * 2.0 < 1.0 {
        return q;
    }
    if t * 3.0 < 2.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

use super::rgb::Rgb;

/// Static color conversion helpers (mirrors the C++ `ColorConverter` class).
pub struct ColorConverter;

impl ColorConverter {
    /// Scale the HSL saturation of `rgb` by `factor`, clamped to [0, 1].
    pub fn adjust_saturation(rgb: &Rgb, factor: f32) -> Rgb {
        let mut hsl = rgb.to_hsl();
        hsl.s *= factor;
        if hsl.s > 1.0 {
            hsl.s = 1.0;
        }
        if hsl.s < 0.0 {
            hsl.s = 0.0;
        }
        hsl.to_rgb()
    }
}

mod colorspace;

use colorspace::{ColorConverter, Rgb};

/// Parse a float the way C++ `std::stof` does: skip leading whitespace,
/// consume the longest valid float prefix, ignore trailing garbage.
fn stof(s: &str) -> f32 {
    let t = s.trim_start();
    let bytes = t.as_bytes();
    let mut end = 0;
    let mut seen_digit = false;
    let mut i = 0;

    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        i += 1;
    }
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
        seen_digit = true;
    }
    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            seen_digit = true;
        }
    }
    if seen_digit {
        end = i;
        if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
            let mut j = i + 1;
            if j < bytes.len() && (bytes[j] == b'+' || bytes[j] == b'-') {
                j += 1;
            }
            let exp_start = j;
            while j < bytes.len() && bytes[j].is_ascii_digit() {
                j += 1;
            }
            if j > exp_start {
                end = j;
            }
        }
    }

    if end == 0 {
        // std::stof would throw std::invalid_argument and terminate.
        panic!("stof: no conversion could be performed");
    }
    t[..end].parse::<f32>().unwrap()
}

/// Format a float exactly like C++ `std::cout << value` with default
/// settings: printf "%g" semantics with 6 significant digits.
fn fmt_g(v: f32) -> String {
    let d = v as f64;
    if d.is_nan() {
        return "nan".to_string();
    }
    if d.is_infinite() {
        return if d < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }

    // Exponent of the value rounded to 6 significant digits.
    let sci = format!("{:.5e}", d); // e.g. "4.50000e-1"
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp < -4 || exp >= 6 {
        // Scientific notation; exponent has a sign and at least two digits.
        let mantissa = strip_trailing_zeros(&sci[..epos]);
        format!(
            "{}e{}{:02}",
            mantissa,
            if exp < 0 { '-' } else { '+' },
            exp.abs()
        )
    } else {
        // Fixed notation with 6 significant digits.
        let prec = (5 - exp) as usize;
        strip_trailing_zeros(&format!("{:.*}", prec, d))
    }
}

fn strip_trailing_zeros(s: &str) -> String {
    if s.contains('.') {
        let trimmed = s.trim_end_matches('0');
        trimmed.strip_suffix('.').unwrap_or(trimmed).to_string()
    } else {
        s.to_string()
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut r = 0.5f32;
    let mut g = 0.6f32;
    let mut b = 0.7f32;
    let mut factor = 1.5f32;

    if args.len() > 3 {
        r = stof(&args[1]);
        g = stof(&args[2]);
        b = stof(&args[3]);
    }
    if args.len() > 4 {
        factor = stof(&args[4]);
    }

    let rgb = Rgb::new(r, g, b);
    let result = ColorConverter::adjust_saturation(&rgb, factor);
    println!("{} {} {}", fmt_g(result.r), fmt_g(result.g), fmt_g(result.b));
}

