struct Cfg {
    tohsl64: bool,   // tohsl arithmetic in f64
    wrap_before: bool, // hue wrap before scaling
    normalized: bool,  // hue stored [0,1] via /6
    s_abs: bool,     // s = delta/(1-|2l-1|)
    sf64: bool,      // s*factor in f64
    q_alt: bool,     // q = l+l*s / l+s*(1-l)
    q64: bool,       // q,p in f64
    t64: bool,       // tr/tg/tb adds in f64
    tmode1: bool,    // channel t via degrees then /360
    b1: u8,          // first branch order 0,1,2
    b3: u8,          // third branch order 0,1,2
    cond_alt: bool,  // t < 1/6 style conditions
    wrap_ge: bool,   // t >= 1 wrap
}

fn hue2rgb(c: &Cfg, p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 { t += 1.0; }
    if c.wrap_ge { if t >= 1.0 { t -= 1.0; } } else if t > 1.0 { t -= 1.0; }
    let first = if c.cond_alt { t < 1.0 / 6.0 } else { t * 6.0 < 1.0 };
    if first {
        return match c.b1 {
            0 => p + (q - p) * 6.0 * t,
            1 => p + (q - p) * t * 6.0,
            _ => p + (q - p) * (6.0 * t),
        };
    }
    let second = if c.cond_alt { t < 0.5 } else { t * 2.0 < 1.0 };
    if second { return q; }
    let third = if c.cond_alt { t < 2.0 / 3.0 } else { t * 3.0 < 2.0 };
    if third {
        return match c.b3 {
            0 => p + (q - p) * (2.0 / 3.0 - t) * 6.0,
            1 => p + (q - p) * 6.0 * (2.0 / 3.0 - t),
            _ => p + (q - p) * (6.0 * (2.0 / 3.0 - t)),
        };
    }
    p
}

