            wrap_before: cfgn & 2 != 0,
            normalized: cfgn & 4 != 0,
            s_abs: cfgn & 8 != 0,
            sf64: cfgn & 16 != 0,
            q_alt: cfgn & 32 != 0,
            q64: cfgn & 64 != 0,
            t64: cfgn & 128 != 0,
            tmode1: cfgn & 256 != 0,
            b1: ((cfgn >> 9) % 3) as u8,
            b3: ((cfgn >> 9) / 3) as u8,
            cond_alt: cfgn & 512 != 0,
            wrap_ge: cfgn & 1024 != 0,
        };
        let mism = cases
            .iter()
            .filter(|(r, g, b, f, refout)| {
                let (rr, gg, bb) = run(&c, *r, *g, *b, *f);
                format!("{} {} {}", fmt(rr), fmt(gg), fmt(bb)) != *refout
            })
            .count();
        results.push((mism, cfgn));
    }
    results.sort();
    for (mism, cfgn) in results.iter().take(10) {
        println!("cfg {} (b1={} b3={}): {} mismatches", cfgn & 2047, (cfgn >> 9) % 3, (cfgn >> 9) / 3, mism);
    }
}
